WITH base AS (SELECT *, CONCAT_WS(',', country, name) AS country_name_key, CASE WHEN is_active THEN 'Yes' ELSE 'No' END AS is_active_label, COALESCE(city, 'UNKNOWN') AS city_filled FROM customers WHERE segment IS NOT NULL AND segment IN ('Corporate', 'Consumer')) SELECT * FROM (SELECT city, country, segment, age FROM base) src PIVOT (SUM(age) FOR segment IN ('Corporate', 'SMB'));
